import time
import logging
import re
from decimal import Decimal
from taf.transport.ssh import ssh as ssh_manager
import six
from abc import ABCMeta, abstractmethod


@six.add_metaclass(ABCMeta)
class ThroughputChecker(object):
    @abstractmethod
    def __init__(self, **kwargs):
        pass

    @abstractmethod
    def setup(self):
        pass

    @abstractmethod
    def calculate_throughoutput(self):
        pass

    @abstractmethod
    def teardown(self):
        pass

    def _get_current_time(self, time_format="%m/%d %H:%M:%S"):
        date_command = "date +'{time_format}'".format(time_format=time_format)
        current_time = self._executor.execute(command=date_command, connection=self._alias).strip()
        logging.info("Start Time: {}".format(current_time))
        return current_time

    @staticmethod
    def _bytes2kbits(value):
        """
        covert byte number to megabit byte number
        :param int value: byte number
        :return: float kilobit number
        """
        return value * 8 / 1024


class GNBThroughputChecker(ThroughputChecker):
    class Connection(object):
        def __init__(self, address, username=None, password=None, proxy=None):
            self._address = address
            self._username = username
            self._password = password
            self._proxy = proxy

        @property
        def address(self):
            return self._address

        @property
        def username(self):
            return self._username

        @property
        def password(self):
            return self._password

        @property
        def proxy(self):
            return self._proxy

    def __init__(self, connection):
        super(GNBThroughputChecker, self).__init__()
        self._executor = ssh_manager()
        self._connection = connection
        self._alias = "default"
        self.start_time = None

    def setup(self):
        self._prepare_asp1a_connection_for_throughput_check()
        self.start_time = self._get_current_time(time_format="%Y-%m-%d %H:%M:%S")

    def _prepare_asp1a_connection_for_throughput_check(self):
        proxy_alias = None
        if self._connection.proxy:
            proxy_alias = "tmp_common_unit"
            self._executor.connect_to(
                hostname=self._connection.proxy.address,
                username=self._connection.proxy.username,
                password=self._connection.proxy.password,
                alias=proxy_alias)

        self._executor.connect_to(
            hostname=self._connection.address,
            username=self._connection.username,
            password=self._connection.password,
            proxy=proxy_alias,
            alias=self._alias)

        logging.info("asp1a connection created.")
        return self._alias

    def _calculate_throughoutput(self, command, location=None):
        logging.info("Getting throughput by executing command: {}".format(command))
        output = self._executor.execute(command=command, connection=self._alias)
        logging.debug("Throughput output: \n{}".format(output))
        outputs = output.split('\r\n')
        if not outputs:
            logging.info("There is no throughput massage on Gnb "
                         "since start traffic time: {}".format(self.start_time))
            return 0
        num = 0
        total = 0
        for element in outputs:
            if element:
                data = element.split(' ')[location]
                traffic_data = self._split_traffic_data(data)
                total += traffic_data
                num += 1
                logging.info("Traffic data is {} bytes/s".format(traffic_data))
        if total == 0:
            throughput = Decimal(0)
        else:
            throughput = self._bytes2kbits(Decimal(total)) / Decimal(num)
        return throughput

    def _split_traffic_data(self, data):
        raise NotImplementedError

    def teardown(self):
        self._executor.disconnect(connection=self._alias)


class GNBUpLinkThroughputChecker(GNBThroughputChecker):
    def __init__(self, connection):
        super(GNBUpLinkThroughputChecker, self).__init__(connection)
        self._alias = "aspla_ul" + str(time.time())

    def calculate_throughoutput(self, location=14):
        tput_command = r'journalctl --since "{start_time}" | grep rlcPdus'.format(
            start_time=self.start_time
        )
        logging.info("Calculating uplink throughput on Gnb.")
        ul_throughoutput = self._calculate_throughoutput(
            command=tput_command,
            location=location
        )
        logging.info("Uplink throughoutput is {} kbits/s".format(ul_throughoutput))
        return ul_throughoutput

    def _split_traffic_data(self, data):
        return int(data.split('(')[-1])


class GNBDownLinkThroughputChecker(GNBThroughputChecker):
    def __init__(self, connection):
        super(GNBDownLinkThroughputChecker, self).__init__(connection)
        self._alias = "aspla_dl" + str(time.time())

    def calculate_throughoutput(self, location=17, size=3000):
        tput_command = r'journalctl --since "{start_time}" | grep -i SentDataMeasurementCounting'.format(
            start_time=self.start_time
        )
        logging.info("Calculating DL throughput on Gnb.")
        dl_throughoutput = self._calculate_throughoutput(
            command=tput_command,
            location=location
        )
        logging.info("Downlink throughoutput is {} kbits/s".format(dl_throughoutput))
        return dl_throughoutput

    def _split_traffic_data(self, data):
        return int(data.split('|')[-1].split(']')[0])


class LSUThroughputChecker(ThroughputChecker):
    class Connection(object):
        def __init__(self, address, username=None, password=None, proxy=None):
            self._address = address
            self._username = username
            self._password = password
            self._proxy = proxy

        @property
        def address(self):
            return self._address

        @property
        def username(self):
            return self._username

        @property
        def password(self):
            return self._password

        @property
        def proxy(self):
            return self._proxy

    def __init__(self, connection):
        super(LSUThroughputChecker, self).__init__()
        self._executor = ssh_manager()
        self._connection = connection
        self._alias = "default"
        self.start_time = None

    def setup(self):
        self._prepare_lsu_connection_for_throughput_check()
        self.start_time = self._get_current_time()

    def _prepare_lsu_connection_for_throughput_check(self):
        proxy_alias = None
        if self._connection.proxy:
            proxy_alias = "tmp_control_pc"
            self._executor.connect_to(
                hostname=self._connection.proxy.address,
                username=self._connection.proxy.username,
                password=self._connection.proxy.password,
                alias=proxy_alias)

        self._executor.connect_to(
            hostname=self._connection.address,
            username=self._connection.username,
            password=self._connection.password,
            proxy=proxy_alias,
            alias=self._alias)

        logging.info("lsu connection created.")
        return self._alias

    def _calculate_throughoutput(self, command, tput_compile):
        logging.info("Getting throughput by executing command: {}".format(command))
        output = self._executor.execute(
            command=command,
            connection=self._alias
        )
        logging.debug("Throughput output: \n{}".format(output))
        tputs = tput_compile.findall(output)
        if not tputs:
            logging.info("There is no throughput massage on LSU "
                         "since start traffic time: {}".format(self.start_time))
            return 0
        total = 0
        for tput in tputs:
            total += int(tput)
            logging.info("Traffic data is {} byte/s".format(tput))
        if total == 0:
            throughput = Decimal(0)
        else:
            throughput = self._bytes2kbits(Decimal(total)) / Decimal(len(tputs))
        return throughput

    def teardown(self):
        self._executor.disconnect(connection=self._alias)


class LSUDLTroughputChecker(LSUThroughputChecker):
    def __init__(self, connection):
        super(LSUDLTroughputChecker, self).__init__(connection)
        self._alias = "lsu_uu" + str(time.time())

    def calculate_throughoutput(self):
        trcinfo_command = r'/lsu/bin/trcinfo -s "{time}" -p0-5 | grep -i "l3rate"'.format(
            time=self.start_time
        )
        logging.info("Calculating DL throughput on LSU.")
        tput_compile = re.compile(r"RxAm=(\d+)")
        dl_throughoutput = self._calculate_throughoutput(
            command=trcinfo_command,
            tput_compile=tput_compile,
        )
        logging.info("Downlink throughoutput is {} kbits/s".format(dl_throughoutput))
        return dl_throughoutput
